public boolean evenlySpaced(int a, int b, int c)
{
    int largest = 0;
    int smallest = 0;
    int middle =0;
    if( a==b && b==c && c==a)
        return true;
    else
    {
        if(a < b && a < c)
            smallest = a;
        else if (a > b && a > c)
            largest = a;
        else if ((a > b && a < c) || (a < b && a > c))
            middle = a; 
        //for b replace a with b
        if(b < a && b < c)
            smallest = b;
        else if (b > a && b > c)
            largest = b;
        else if ((b > a && b < c) || (b < a && b > c))
            middle = b; 
        // for c
        if(c < b && c < a)
            smallest = c;
        else if (c > b && c > a)
            largest = c;
        else if ((c > a && c < b) || (c < a && c > b))
            middle = c; 
        
        if((middle-smallest) == (largest-middle))
            return true;
        else
            return false; 
    }
}

