public int[] tenRun(int[] nums)
{
    if(nums.length <= 1)
    {
        return nums;
    }
    if(nums.length == 2 && nums[0]%10 != 0)
    {
        return nums;
    }
    int i = 0;
    while(nums[i]%10 != 0)
    {
        i++;
    }
    int j = i;
    while(nums[j]%10 == 0 && j < nums.length-1)
    {
        int convert = nums[j];
        if((j+1) <= nums.length-1 && nums[j+1]%10 == 0 && nums[j+1] != nums[j])
        {
            if((j+1) == nums.length-1)
            {
                return nums;
            }
            convert = nums[j+1];
            j++;
        }
        nums[j+1] = convert;
        j++;
    }
    return nums;
}

