public boolean canBalance(int[] nums)
{
    int count = 0;
    for(int i =0; i < nums.length; i++)
    {
        int sumLeft = 0;
        int sumRight = 0;
        for(int x = 0; x < i; x++)
        {
            sumLeft += nums[x];
        }
        for(int y = nums.length -1; y >= i; y--)
        {
            sumRight += nums[y];
        }
        
        if(sumLeft == sumRight)
        {
            count++;
        }
    }
    if(count > 0)
    {
        return true;
    }
    else
    {
        return false;
    }
}

