    {
        return nums;
    }
    int store = 0;
    int start = nums[0];
    if(nums.length == 2)
    {
        nums[0] = nums[1];
        nums[1] = start;
        return nums;
    }
    for(int x = 1; x < nums.length-1; x++)
    {
        store = nums[x];
        nums[x] = nums[x+1];
        nums[x-1] = store; 
    }
    nums[nums.length-1] = start;
    return nums;
}

